insert into public.products (id, cat, sub, brand, origin, name, vol, price, sale, is_new, in_stock, pop, actives, skin, concerns, images, descr, howto, ingredients, shape, tint) values
(1, 'skincare', 'Làm sạch', 'Mizu Lab', 'Nhật', 'Dầu tẩy trang trà xanh', '200ml', 690000, null, false, true, 9, array['Trà xanh']::text[], array['Da dầu','Da hỗn hợp']::text[], array['Mụn','Lỗ chân lông']::text[], '{}'::text[], 'Dầu tẩy trang nhũ hoá nhanh, hoà tan kem chống nắng và lớp trang điểm lâu trôi mà không để lại cảm giác nhờn. Chiết xuất trà xanh giúp làm dịu và hạn chế bít tắc lỗ chân lông.', 'Lấy 2–3 lần nhấn ra tay khô, massage lên mặt khô khoảng 1 phút. Thêm chút nước để nhũ hoá rồi rửa sạch, sau đó dùng sữa rửa mặt.', '', 'pump', '#e9efe2'),
(2, 'skincare', 'Làm sạch', 'Seoul Bloom', 'Hàn', 'Sữa rửa mặt amino dịu nhẹ', '150ml', 450000, 380000, false, true, 8, array['Amino acid']::text[], array['Da nhạy cảm','Da khô']::text[], array['Nhạy cảm']::text[], '{}'::text[], 'Sữa rửa mặt pH thấp với chất làm sạch gốc amino, tạo bọt mịn, làm sạch mà không gây khô căng. Phù hợp da nhạy cảm và da đang treatment.', 'Tạo bọt với nước, massage nhẹ lên da ướt 30–60 giây rồi rửa sạch. Dùng sáng và tối.', '', 'tube', '#f3e3dc'),
(3, 'skincare', 'Toner', 'Aurelle', 'Pháp', 'Toner BHA 2% thông thoáng lỗ chân lông', '150ml', 790000, null, true, true, 7, array['BHA']::text[], array['Da dầu','Da hỗn hợp']::text[], array['Mụn','Lỗ chân lông']::text[], '{}'::text[], 'Toner chứa 2% BHA (salicylic acid) tan trong dầu, len sâu vào lỗ chân lông để làm sạch bã nhờn, giảm mụn đầu đen và giúp bề mặt da mịn hơn.', 'Thấm ra bông tẩy trang, lau nhẹ toàn mặt sau bước rửa mặt, buổi tối. Bắt đầu 2–3 lần/tuần. Dùng kem chống nắng ban ngày.', '', 'bottle', '#e8e6f0'),
(4, 'skincare', 'Toner', 'Seoul Bloom', 'Hàn', 'Toner HA cấp ẩm 5 tầng', '300ml', 620000, null, false, true, 7, array['Hyaluronic Acid']::text[], array['Da khô','Mọi loại da']::text[], array['Cấp ẩm']::text[], '{}'::text[], 'Toner dạng nước hơi sánh với 5 loại hyaluronic acid kích thước khác nhau, cấp ẩm từ bề mặt đến các lớp sâu, giúp da căng mọng và hấp thụ các bước sau tốt hơn.', 'Cho ra lòng bàn tay, vỗ nhẹ lên da. Có thể lặp lại 2–3 lớp với da khô.', '', 'bottle', '#e4ecf1'),
(5, 'skincare', 'Serum', 'Aurelle', 'Pháp', 'Serum Niacinamide 10% làm sáng', '30ml', 1150000, null, false, true, 10, array['Niacinamide','Kẽm']::text[], array['Da dầu','Da hỗn hợp']::text[], array['Thâm & sáng da','Lỗ chân lông']::text[], '{}'::text[], 'Serum 10% niacinamide kết hợp kẽm giúp làm mờ thâm, đều màu da, kiểm soát dầu và thu nhỏ lỗ chân lông. Kết cấu mỏng nhẹ, thấm nhanh.', 'Dùng 3–4 giọt sau toner, sáng và tối. Không nên dùng chung bước với vitamin C nồng độ cao.', '', 'dropper', '#f2e6d6'),
(6, 'skincare', 'Serum', 'Maison Rosé', 'Pháp', 'Serum Vitamin C 15% đều màu da', '30ml', 1390000, 1190000, false, true, 9, array['Vitamin C']::text[], array['Mọi loại da']::text[], array['Thâm & sáng da']::text[], '{}'::text[], 'Vitamin C 15% dạng ổn định giúp làm sáng da, mờ thâm sau mụn và tăng khả năng bảo vệ da trước tác hại môi trường khi dùng cùng kem chống nắng.', 'Dùng 3–4 giọt buổi sáng sau toner, trước kem dưỡng và kem chống nắng. Đậy kín nắp, bảo quản nơi mát.', '', 'dropper', '#fbecd6'),
(7, 'skincare', 'Serum', 'Aurelle', 'Pháp', 'Retinol 0.3% chống lão hoá ban đêm', '30ml', 1480000, null, false, true, 6, array['Retinol']::text[], array['Da khô','Da hỗn hợp']::text[], array['Lão hoá']::text[], '{}'::text[], 'Retinol 0.3% trong nền kem dưỡng giúp cải thiện nếp nhăn nhỏ, làm mịn bề mặt và đều màu da. Nồng độ phù hợp cho người mới bắt đầu dùng retinol.', 'Buổi tối, lấy lượng bằng hạt đậu thoa đều sau toner. Bắt đầu 2 lần/tuần rồi tăng dần. Bắt buộc dùng kem chống nắng ban ngày. Không dùng khi mang thai.', '', 'dropper', '#ead9e3'),
(8, 'skincare', 'Serum', 'Seoul Bloom', 'Hàn', 'Serum rau má làm dịu da mụn', '50ml', 690000, null, true, true, 8, array['Rau má','Panthenol']::text[], array['Da nhạy cảm','Da dầu']::text[], array['Nhạy cảm','Mụn']::text[], '{}'::text[], 'Serum chiết xuất rau má và panthenol giúp làm dịu da đỏ rát, hỗ trợ phục hồi vùng da mụn và da yếu sau treatment.', 'Dùng 3–4 giọt sau toner, sáng và tối. Có thể chấm thêm lên vùng da đang kích ứng.', '', 'dropper', '#e3eee6'),
(9, 'skincare', 'Kem dưỡng', 'Hana Derm', 'Hàn', 'Kem Ceramide phục hồi hàng rào da', '50ml', 980000, null, false, true, 9, array['Ceramide','Panthenol']::text[], array['Da khô','Da nhạy cảm']::text[], array['Nhạy cảm','Cấp ẩm']::text[], '{}'::text[], 'Kem dưỡng với phức hợp ceramide giúp củng cố hàng rào bảo vệ da, khoá ẩm lâu và giảm cảm giác khô ráp, bong tróc.', 'Bước cuối chu trình dưỡng buổi tối, hoặc trước kem chống nắng buổi sáng. Lấy lượng vừa đủ thoa đều.', '', 'jar', '#f5e9e2'),
(10, 'skincare', 'Kem dưỡng', 'Mizu Lab', 'Nhật', 'Kem mắt peptide giảm bọng', '15ml', 1320000, null, true, true, 5, array['Peptide']::text[], array['Mọi loại da']::text[], array['Lão hoá']::text[], '{}'::text[], 'Kem mắt chứa peptide giúp làm săn vùng da quanh mắt, giảm bọng và nếp nhăn nhỏ. Kết cấu mềm, không gây cộm khi trang điểm.', 'Lấy lượng bằng hạt gạo, dùng ngón áp út vỗ nhẹ quanh hốc mắt, sáng và tối.', '', 'jar', '#efe4ef'),
(11, 'skincare', 'Kem dưỡng', 'Hana Derm', 'Hàn', 'Gel dưỡng HA mỏng nhẹ cho da dầu', '50ml', 720000, 590000, false, true, 6, array['Hyaluronic Acid']::text[], array['Da dầu']::text[], array['Cấp ẩm']::text[], '{}'::text[], 'Gel dưỡng ẩm không dầu, thấm nhanh, cấp nước cho da dầu mà không gây bóng nhờn hay bít tắc.', 'Thoa một lớp mỏng sau serum, sáng và tối.', '', 'jar', '#e6eef0'),
(12, 'skincare', 'Chống nắng', 'Mizu Lab', 'Nhật', 'Kem chống nắng SPF50+ PA++++', '60ml', 560000, null, false, true, 10, array['Màng lọc thế hệ mới']::text[], array['Mọi loại da']::text[], array['Thâm & sáng da']::text[], '{}'::text[], 'Kem chống nắng phổ rộng SPF50+ PA++++, kết cấu tinh chất mỏng nhẹ, không vệt trắng, chịu nước tốt. Bước quan trọng nhất để ngừa thâm và lão hoá.', 'Thoa lượng khoảng 2 đốt ngón tay cho mặt và cổ, 15 phút trước khi ra nắng. Thoa lại sau mỗi 2–3 giờ khi ở ngoài trời.', '', 'tube', '#fbf0d9'),
(13, 'skincare', 'Chống nắng', 'Maison Rosé', 'Pháp', 'Sữa chống nắng nâng tone', '50ml', 620000, 520000, false, true, 7, array['Niacinamide']::text[], array['Da dầu','Da hỗn hợp']::text[], array['Thâm & sáng da']::text[], '{}'::text[], 'Sữa chống nắng nâng tone nhẹ tự nhiên, có thêm niacinamide hỗ trợ đều màu da. Có thể dùng thay kem lót.', 'Lắc đều trước khi dùng. Thoa bước cuối buổi sáng, trước trang điểm.', '', 'tube', '#f6e4e0'),
(14, 'skincare', 'Tẩy tế bào chết', 'Aurelle', 'Pháp', 'Tẩy da chết AHA 8% làm mịn', '100ml', 860000, null, true, true, 6, array['AHA']::text[], array['Da khô','Da hỗn hợp']::text[], array['Thâm & sáng da','Lão hoá']::text[], '{}'::text[], 'Dung dịch AHA 8% (glycolic acid) loại bỏ lớp tế bào chết bề mặt, giúp da sáng mịn và đều màu hơn.', 'Buổi tối, thấm ra bông lau toàn mặt sau rửa mặt, 2–3 lần/tuần. Không dùng cùng đêm với retinol. Dùng kem chống nắng ban ngày.', '', 'bottle', '#f3ead8'),
(15, 'skincare', 'Mặt nạ', 'Seoul Bloom', 'Hàn', 'Mặt nạ ngủ rau má làm dịu', '80ml', 540000, null, false, true, 4, array['Rau má']::text[], array['Da nhạy cảm','Mọi loại da']::text[], array['Nhạy cảm','Cấp ẩm']::text[], '{}'::text[], 'Mặt nạ ngủ dạng gel mát, làm dịu và cấp ẩm qua đêm, giúp da sáng hôm sau mềm và bớt đỏ.', 'Thoa một lớp vừa phải ở bước cuối buổi tối, 2–3 lần/tuần. Rửa sạch vào sáng hôm sau.', '', 'jar', '#e3eee6'),
(16, 'makeup', 'Nền', 'Seoul Bloom', 'Hàn', 'Cushion lâu trôi tone 21', '15g', 820000, null, false, true, 8, '{}'::text[], array['Da dầu','Da hỗn hợp']::text[], '{}'::text[], '{}'::text[], 'Cushion che phủ trung bình, lớp nền mỏng mịn, kiềm dầu và giữ lớp nền ổn định suốt ngày dài. Tone 21 hợp da sáng tự nhiên.', 'Dặm nhẹ bông phấn từ giữa mặt ra ngoài, tán thêm lớp thứ hai ở vùng cần che phủ.', '', 'compact', '#f3e2d4'),
(17, 'makeup', 'Nền', 'Maison Rosé', 'Pháp', 'Kem nền mỏng nhẹ có HA', '30ml', 1250000, null, true, true, 6, array['Hyaluronic Acid']::text[], array['Da khô']::text[], '{}'::text[], '{}'::text[], 'Kem nền finish căng bóng tự nhiên, có hyaluronic acid giữ ẩm cho da khô, không lộ vảy.', 'Lấy 1 lần nhấn, tán đều bằng mút ẩm hoặc cọ.', '', 'pump', '#f1e1d3'),
(18, 'makeup', 'Nền', 'Mizu Lab', 'Nhật', 'Phấn phủ kiềm dầu', '10g', 560000, null, false, true, 7, '{}'::text[], array['Da dầu']::text[], '{}'::text[], '{}'::text[], 'Phấn phủ dạng bột siêu mịn, kiềm dầu và cố định lớp nền, không làm da trông khô hay xám.', 'Dùng cọ lớn phủ nhẹ vùng chữ T và toàn mặt sau lớp nền.', '', 'compact', '#f4ece4'),
(19, 'makeup', 'Môi', 'Maison Rosé', 'Pháp', 'Son thỏi lì màu hồng đất', '3.5g', 890000, null, false, true, 10, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Son thỏi chất lì mềm mịn, lên màu chuẩn ngay lần đầu, không gây khô môi. Màu hồng đất dễ dùng hằng ngày.', 'Thoa trực tiếp lên môi, có thể tán nhẹ viền môi bằng ngón tay để có hiệu ứng mềm.', '', 'lipstick', '#f0d6d0'),
(20, 'makeup', 'Môi', 'Seoul Bloom', 'Hàn', 'Son tint bóng màu nude', '4g', 390000, 320000, false, true, 7, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Son tint bóng nhẹ, lên màu nude trong trẻo, giữ màu tốt sau khi lớp bóng phai.', 'Thoa lòng môi rồi mím nhẹ để màu loang tự nhiên.', '', 'tint', '#f6dcd5'),
(21, 'makeup', 'Má & mắt', 'Mizu Lab', 'Nhật', 'Phấn má kem màu đào', '6g', 650000, null, false, true, 6, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Má hồng dạng kem tan vào da, tạo sắc hồng đào tự nhiên như từ bên trong. Dùng được cho cả môi và mắt.', 'Chấm 2–3 điểm lên gò má, tán đều bằng ngón tay hoặc mút.', '', 'compact', '#f7ddd2'),
(22, 'makeup', 'Má & mắt', 'Hana Derm', 'Hàn', 'Bảng mắt 4 ô tone be', '6g', 720000, null, false, true, 5, '{}'::text[], '{}'::text[], '{}'::text[], '{}'::text[], 'Bảng mắt 4 màu be, nâu sữa và ánh nhũ nhẹ, dễ phối cho trang điểm đi làm và đi chơi.', 'Dùng màu sáng làm nền, màu đậm hơn nhấn bầu mắt và đuôi mắt, nhũ ở giữa mí.', '', 'compact', '#ece0d2')
